package com.civicpulse.controller; import com.civicpulse.dto.AuthDtos.*; import com.civicpulse.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService service;public AuthController(AuthService service){this.service=service;}@PostMapping("/register") public AuthResponse register(@RequestBody @Valid RegisterRequest r){return service.register(r);}@PostMapping("/login") public AuthResponse login(@RequestBody @Valid LoginRequest r){return service.login(r);}}
